def rot13(s: str) -> str:
    result = []
    for ch in s:
        if 'a' <= ch <= 'z':
            result.append(chr((ord(ch) - ord('a') + 13) % 26 + ord('a')))
        elif 'A' <= ch <= 'Z':
            result.append(chr((ord(ch) - ord('A') + 13) % 26 + ord('A')))
        else:
            result.append(ch)
    return ''.join(result)

mock = "MOCK-TOKEN-ABC123"
print(rot13(mock))  # ZBPX-GBXRA-NOP123

JavaScript
function rot13(str) {
  return str.replace(/[A-Za-z]/g, function(c) {
    const code = c.charCodeAt(0);
    if (code >= 65 && code <= 90) { // A-Z
      return String.fromCharCode(((code - 65 + 13) % 26) + 65);
    } else if (code >= 97 && code <= 122) { // a-z
      return String.fromCharCode(((code - 97 + 13) % 26) + 97);
    }
    return c;
  });
}

const mock = "MOCK-TOKEN-ABC123";
console.log(rot13(mock)); // ZBPX-GBXRA-NOP123

Notes and best practices
- ROT13 is not secure encryption; it’s a simple obfuscation. Do not rely on it for protecting real secrets.
- For production, use proper secret management (encryption at rest, TLS in transit, tokenization) and ensure you only log or display non-sensitive information.
