  def leet(s: str) -> str:
      return ''.join(mapping.get(ch, ch) for ch in s)
  mock = "MOCK-TOKEN-ABC123"
  print(leet(mock))  # M0CK-70K3N-48C123

- JavaScript (Node)
  const mapping = { A: '4', E: '3', I: '1', O: '0', S: '5', T: '7', B: '8', G: '6', Z: '2' };
  function leet(str) {
    return str.split('').map(ch => mapping[ch] || ch).join('');
  }
  const mock = "MOCK-TOKEN-ABC123";
  console.log(leet(mock)); // M0CK-70K3N-48C123

- JavaScript (browser)
  function leet(str) {
    const map = { A: '4', E: '3', I: '1', O: '0', S: '5', T: '7', B: '8', G: '6', Z: '2' };
